/* Match the page canvas to the shared SaunaFab palette. */
body:has(:is(.sf-panier-v2, #sf-panier-v2)) {
    background: var(--sf-blue, #16354b);
    font-family: var(--sf-font-body, "DM Sans", Arial, sans-serif);
}

/* Accept an Elementor class or ID. Only the outer wrapper gets the layout spacing. */
:is(.sf-panier-v2, #sf-panier-v2):not(:is(.sf-panier-v2, #sf-panier-v2) *) {
    --sf-cart-border: rgba(22, 53, 75, .18);
    --sf-cart-navy: var(--sf-blue, #16354b);
    --sf-cart-panel: var(--sf-cream, #f3eee4);
    --sf-cart-panel-radius: 28px;
    --sf-cart-ivory: var(--sf-white, #faf8f3);
    box-sizing: border-box;
    width: var(--sf-aligned-width, min(1180px, calc(100% - 38px)));
    max-width: 100%;
    margin-inline: auto;
    margin-block: clamp(24px, 5vw, 64px);
    padding: clamp(18px, 4vw, 40px);
    border: 0;
    box-shadow: none;
    background: transparent;
    color: var(--sf-cart-navy);
    font-family: var(--sf-font-body, "DM Sans", Arial, sans-serif);
}

/* Stack the two Royal Addons cart sections and let the Elementor background show through. */
:is(.sf-panier-v2, #sf-panier-v2) .wpr-cart-wrapper {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: clamp(20px, 4vw, 40px);
    border: 0;
    box-shadow: none;
    background: transparent;
}

:is(.sf-panier-v2, #sf-panier-v2) .wpr-cart-wrapper > * {
    flex: 0 0 auto;
    width: 100%;
    max-width: none;
    min-width: 0;
    margin-inline: 0;
}

/* Support WooCommerce's classic table and Cart block markup. */
:is(.sf-panier-v2, #sf-panier-v2) :is(.woocommerce-cart-form, .cart_totals, .wc-block-cart__main, .wc-block-cart__sidebar) {
    min-width: 0;
    color: var(--sf-cart-navy);
}

:is(.sf-panier-v2, #sf-panier-v2) :is(.elementor-widget-text-editor, .wpr-cart-wrapper, .woocommerce, .wc-block-cart, table.shop_table, th, td, label, input, select, button, a, .woocommerce-info) {
    font-family: var(--sf-font-body, "DM Sans", Arial, sans-serif);
}

/* Use the same title treatment as the navy introductions on the homepage. */
:is(.sf-panier-v2, #sf-panier-v2) :is(.elementor-heading-title, h1) {
    margin: 0;
    color: var(--sf-cart-ivory);
    font: 500 clamp(52px, 8vw, 104px)/.98 var(--sf-font-heading, "Playfair Display", Georgia, serif);
    letter-spacing: -.045em;
}

:is(.sf-panier-v2, #sf-panier-v2) .elementor-widget-heading:has(.elementor-heading-title)::before {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 20px;
    color: var(--sf-yellow, #ecd8a9);
    font: 600 11px/1.4 var(--sf-font-body, "DM Sans", Arial, sans-serif);
    letter-spacing: .24em;
    text-transform: uppercase;
    padding-inline-start: 46px;
    background: linear-gradient(currentColor, currentColor) left center / 32px 1px no-repeat;
    content: "Boutique";
}

:is(.sf-panier-v2, #sf-panier-v2) > .e-con-inner > .elementor-widget-text-editor,
:is(.sf-panier-v2, #sf-panier-v2) > .elementor-widget-text-editor {
    color: var(--sf-cart-ivory);
}

:is(.sf-panier-v2, #sf-panier-v2) :is(.cart_totals h2, .cart_totals h3, .wc-block-cart__totals-title) {
    color: var(--sf-cart-navy);
    font: 500 clamp(25px, 3vw, 38px)/1.1 var(--sf-font-heading, "Playfair Display", Georgia, serif);
}

:is(.sf-panier-v2, #sf-panier-v2) table.shop_table {
    border: 0;
    box-shadow: none;
}

/* Keep table headers, alternating rows and hover states on the same panel color. */
:is(.sf-panier-v2, #sf-panier-v2) :is(table.shop_table, .wc-block-cart-items),
:is(.sf-panier-v2, #sf-panier-v2) :is(table.shop_table, .wc-block-cart-items) :is(thead, tbody, tfoot, tr, th, td) {
    background: var(--sf-cart-panel) !important;
}

:is(.sf-panier-v2, #sf-panier-v2) :is(.woocommerce-cart-form, .cart_totals, .wc-block-cart__main, .wc-block-cart__sidebar) {
    box-sizing: border-box;
    padding: clamp(16px, 3vw, 36px);
    border: 0;
    border-radius: var(--sf-cart-panel-radius);
    box-shadow: none;
    background: var(--sf-cart-panel);
}

:is(.sf-panier-v2, #sf-panier-v2) :is(.product-name, .wc-block-components-product-name) a,
:is(.sf-panier-v2, #sf-panier-v2) a.wc-block-components-product-name {
    color: var(--sf-cart-navy);
    font-weight: 600;
}

:is(.sf-panier-v2, #sf-panier-v2) :is(.variation, .wc-block-components-product-details) {
    font-size: 14px;
    line-height: 1.5;
}

:is(.sf-panier-v2, #sf-panier-v2) :is(input.qty, .coupon input.input-text, .wc-block-components-quantity-selector) {
    border: 1px solid var(--sf-cart-border);
    border-radius: 8px;
    background: #fff;
    color: var(--sf-cart-navy);
}

:is(.sf-panier-v2, #sf-panier-v2) :is(.coupon .button, button[name="update_cart"], .checkout-button, .wc-block-cart__submit-button, .return-to-shop a.button) {
    min-height: 44px;
    padding: 10px 18px;
    border: 1px solid var(--sf-cart-navy);
    border-radius: 999px;
    font: 600 14px/1.4 var(--sf-font-body, "DM Sans", Arial, sans-serif);
}

:is(.sf-panier-v2, #sf-panier-v2) :is(.coupon .button, button[name="update_cart"]) {
    background: transparent;
    color: var(--sf-cart-navy);
}

:is(.sf-panier-v2, #sf-panier-v2) :is(.checkout-button, .wc-block-cart__submit-button, .return-to-shop a.button) {
    background: var(--sf-cart-navy);
    color: var(--sf-cart-ivory);
}

:is(.sf-panier-v2, #sf-panier-v2) :is(.checkout-button, .wc-block-cart__submit-button, .return-to-shop a.button):hover {
    background: var(--sf-ink, #201d1a);
    color: var(--sf-cart-ivory);
}

:is(.sf-panier-v2, #sf-panier-v2) :is(a, button, input):focus-visible {
    outline: 2px solid var(--sf-cart-navy);
    outline-offset: 3px;
}

:is(.sf-panier-v2, #sf-panier-v2) .woocommerce:has(.cart-empty.woocommerce-info) {
    padding: clamp(20px, 4vw, 40px);
    border-radius: var(--sf-cart-panel-radius);
    background: var(--sf-cart-panel);
}

:is(.sf-panier-v2, #sf-panier-v2) .cart-empty.woocommerce-info {
    margin: 0 0 16px;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--sf-cart-navy);
    font-size: 17px;
}

:is(.sf-panier-v2, #sf-panier-v2) .cart-empty.woocommerce-info::before { content: none; }
:is(.sf-panier-v2, #sf-panier-v2) .return-to-shop { margin-bottom: 0; }

/* Style the Royal Addons item table without changing WooCommerce's cart controls. */
:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table.woocommerce-cart-form__contents {
    width: 100%;
    margin: 0;
    border-collapse: collapse;
    color: var(--sf-cart-navy);
    font-size: 14px;
    line-height: 1.45;
}

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table.woocommerce-cart-form__contents :is(th, td) {
    padding: 14px clamp(8px, 1.5vw, 18px);
    border: 0;
    border-bottom: 1px solid var(--sf-cart-border);
    color: var(--sf-cart-navy);
    vertical-align: top;
}

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table.woocommerce-cart-form__contents thead th {
    padding-block-start: 4px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: .08em;
    text-transform: uppercase;
}

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table .product-remove { width: 40px; }
:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table .product-thumbnail { width: 96px; }
:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table .product-name { width: 46%; }
:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table :is(.product-price, .product-quantity, .product-subtotal) {
    text-align: end;
    font-variant-numeric: tabular-nums;
}

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table td.product-thumbnail img {
    display: block;
    width: clamp(54px, 8vw, 88px);
    max-width: 100%;
    height: auto;
    aspect-ratio: 1;
    border-radius: 12px;
    object-fit: cover;
}

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table td.product-name > a {
    color: var(--sf-cart-navy);
    font: 600 clamp(18px, 2.2vw, 25px)/1.2 var(--sf-font-heading, "Playfair Display", Georgia, serif);
    text-decoration: none;
}

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table td.product-name > a:hover { text-decoration: underline; }

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table td.product-name dl.variation {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr);
    gap: 4px 10px;
    margin: 10px 0 0;
    font-size: 13px;
    overflow-wrap: anywhere;
}

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table dl.variation :is(dt, dd, p) {
    float: none;
    margin: 0;
}

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table td.product-subtotal { font-weight: 700; }

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table .product-remove a.remove {
    display: grid;
    place-items: center;
    width: 30px;
    height: 30px;
    border: 1px solid var(--sf-cart-border);
    border-radius: 50%;
    background: transparent;
    color: var(--sf-cart-navy) !important;
    font-size: 19px;
    text-decoration: none;
}

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table .product-remove a.remove:hover {
    background: var(--sf-cart-navy);
    color: var(--sf-cart-ivory) !important;
}

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table td.actions {
    padding: 20px 0 0;
    border-bottom: 0;
}

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table td.actions .coupon {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}

:is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table td.actions .coupon .input-text {
    width: min(100%, 220px);
    min-height: 44px;
    margin: 0;
    padding: 8px 12px;
}

@media (max-width: 767px) {
    :is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table.woocommerce-cart-form__contents thead {
        position: absolute;
        width: 1px;
        height: 1px;
        overflow: hidden;
        clip-path: inset(50%);
    }

    :is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table.woocommerce-cart-form__contents :is(tbody, tr, td) {
        display: block;
        width: 100%;
    }

    :is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table tr.cart_item {
        position: relative;
        padding-block: 12px;
        border-bottom: 1px solid var(--sf-cart-border);
    }

    :is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table tr.cart_item td {
        padding: 6px 0;
        border: 0;
        text-align: start !important;
    }

    :is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table tr.cart_item td.product-remove {
        position: absolute;
        inset: 12px 0 auto auto;
        width: auto;
        padding: 0;
    }

    :is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table tr.cart_item td.product-name {
        padding-inline-end: 38px;
    }

    :is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table tr.cart_item :is(.product-thumbnail, .product-name)::before {
        content: none;
    }

    :is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table tr.cart_item :is(.product-price, .product-quantity, .product-subtotal) {
        display: flex;
        justify-content: space-between;
        align-items: baseline;
        gap: 12px;
    }

    :is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table tr.cart_item :is(.product-price, .product-quantity, .product-subtotal)[data-title]::before {
        content: attr(data-title);
        font-weight: 600;
    }

    :is(.sf-panier-v2, #sf-panier-v2) .wpr-shop-table td.actions .coupon {
        float: none;
        margin-bottom: 12px;
    }
}

/* Give cart notices the same palette and rounding as the purchase panels. */
:is(.sf-panier-v2, #sf-panier-v2) .woocommerce-notices-wrapper > :is(.woocommerce-message, .woocommerce-error, .woocommerce-info:not(.cart-empty)) {
    --sf-cart-notice-accent: var(--sf-yellow, #ecd8a9);
    box-sizing: border-box;
    margin: 0 0 16px;
    padding: 14px 18px;
    border: 0;
    border-inline-start: 4px solid var(--sf-cart-notice-accent);
    border-radius: 14px;
    background: var(--sf-cart-panel, #f3eee4);
    color: var(--sf-cart-navy, #16354b);
    font: 400 15px/1.5 var(--sf-font-body, "DM Sans", Arial, sans-serif);
}

:is(.sf-panier-v2, #sf-panier-v2) .woocommerce-notices-wrapper > .woocommerce-error {
    --sf-cart-notice-accent: #a54b46;
    padding-inline-start: 32px;
}

:is(.sf-panier-v2, #sf-panier-v2) .woocommerce-notices-wrapper > :is(.woocommerce-message, .woocommerce-error, .woocommerce-info:not(.cart-empty))::before {
    content: none;
}

:is(.sf-panier-v2, #sf-panier-v2) .woocommerce-message .restore-item {
    display: inline-block;
    margin-inline-start: 8px;
    color: var(--sf-cart-navy, #16354b);
    font-weight: 700;
    text-decoration: underline;
    text-underline-offset: 3px;
}

:is(.sf-panier-v2, #sf-panier-v2) .woocommerce-message .restore-item:hover {
    text-decoration-thickness: 2px;
}
